// Parse command
const message = $input.item.json.message;
const text = message.text || '';
const match = text.match(/^\/([\w]+)(?:\s+(.*))?$/);

if (!match) return { json: { isValid: false } };

const command = match[1].toLowerCase();
const args = match[2]?.trim() || '';

return {
  json: {
    isValid: true,
    command,
    args,
    chatId: message.chat.id,
    userId: message.from.id,
    username: message.from.username,
    messageId: message.message_id
  }
};

// Parse report arguments
const input = $input.item.json;
const args = input.args;
const today = new Date();
const fmt = d => d.toISOString().split('T')[0];

let startDate, endDate;

if (!args || args === 'today') {
  startDate = endDate = fmt(today);
} else if (args === 'week') {
  const weekAgo = new Date(today);
  weekAgo.setDate(weekAgo.getDate() - 7);
  startDate = fmt(weekAgo);
  endDate = fmt(today);
} else if (args === 'month') {
  const monthAgo = new Date(today);
  monthAgo.setMonth(monthAgo.getMonth() - 1);
  startDate = fmt(monthAgo);
  endDate = fmt(today);
} else {
  const match = args.match(/(\d{1,2})\.(\d{1,2})-(\d{1,2})\.(\d{1,2})/);
  if (match) {
    const y = today.getFullYear();
    startDate = `${y}-${match[2].padStart(2,'0')}-${match[1].padStart(2,'0')}`;
    endDate = `${y}-${match[4].padStart(2,'0')}-${match[3].padStart(2,'0')}`;
  } else {
    startDate = endDate = fmt(today);
  }
}

return { json: { ...input, startDate, endDate } };

// Build report
const candidates = $input.all().map(i => i.json).filter(c => c.id);
const parseData = $('Parse Report Args').item.json;
const { startDate, endDate, chatId, messageId } = parseData;

const fmtDate = d => new Date(d).toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' });

let text = `📊 *Отчёт по кандидатам*\n📅 ${fmtDate(startDate)} — ${fmtDate(endDate)}\n\n`;

if (!candidates.length) {
  text += '_Кандидатов не найдено._';
} else {
  const byStatus = {};
  candidates.forEach(c => {
    if (!byStatus[c.status]) byStatus[c.status] = [];
    byStatus[c.status].push(c);
  });

  text += `👥 Всего: ${candidates.length}\n\n`;

  const emoji = { 'направлен': '📋', 'собеседование': '🗣', 'оформление': '📝', 'работает': '✅', 'отказ': '❌', 'архив': '📦' };
  Object.entries(byStatus).forEach(([status, list]) => {
    text += `${emoji[status] || '•'} ${status}: ${list.length}\n`;
  });

  text += '\n*Последние 10:*\n';
  candidates.slice(0, 10).forEach((c, i) => {
    text += `\n${i+1}. *${c.full_name}*\n   📞 ${c.phone} | 💼 ${c.position}\n   📊 ${c.status}\n`;
  });

  if (candidates.length > 10) text += `\n_...и ещё ${candidates.length - 10}_`;
}

const keyboard = {
  inline_keyboard: [
    [{ text: '📥 Excel', callback_data: `export_candidates_${startDate}_${endDate}` }],
    [{ text: '📊 Воронка', callback_data: 'report_funnel' }, { text: '👥 Рекрутеры', callback_data: 'report_recruiters' }]
  ]
};

return { json: { text, keyboard, chatId, messageId } };

// Build funnel stats
const stats = $input.all().map(i => i.json).filter(s => s.status);
const cmdData = $('Parse Command').item.json;

let text = '📊 *Воронка найма*\n📅 Последние 30 дней\n\n';

const emoji = { 'направлен': '📋', 'собеседование': '🗣', 'оформление': '📝', 'работает': '✅', 'отказ': '❌', 'архив': '📦' };
const total = stats.reduce((s, r) => s + parseInt(r.count || 0), 0);

stats.forEach(s => {
  const pct = total > 0 ? Math.round((s.count / total) * 100) : 0;
  const bar = '█'.repeat(Math.round(pct / 5));
  text += `${emoji[s.status] || '•'} *${s.status}*: ${s.count} (${pct}%)\n   ${bar}\n\n`;
});

const hired = stats.find(s => s.status === 'работает')?.count || 0;
const conversion = total > 0 ? Math.round((hired / total) * 100) : 0;
text += `\n📈 *Конверсия:* ${conversion}%`;

return { json: { text, chatId: cmdData.chatId, messageId: cmdData.messageId } };

// Parse export args
const input = $input.item.json;
const args = input.args.split(' ');
const exportType = args[0] || 'candidates';
const period = args[1] || 'month';

const today = new Date();
const fmt = d => d.toISOString().split('T')[0];

let startDate, endDate = fmt(today);
if (period === 'week') {
  const d = new Date(today); d.setDate(d.getDate() - 7);
  startDate = fmt(d);
} else {
  const d = new Date(today); d.setMonth(d.getMonth() - 1);
  startDate = fmt(d);
}

return { json: { ...input, exportType, startDate, endDate } };

// Convert to CSV
const data = $input.all().map(i => i.json).filter(r => r.id);
const exportArgs = $('Parse Export Args').item.json;

if (!data.length) {
  return { json: { hasData: false, chatId: exportArgs.chatId, messageId: exportArgs.messageId } };
}

const headers = Object.keys(data[0]);
let csv = headers.join(';') + '\n';
data.forEach(row => {
  csv += headers.map(h => {
    let val = row[h];
    if (val === null || val === undefined) val = '';
    if (typeof val === 'string' && (val.includes(';') || val.includes('"') || val.includes('\n'))) {
      val = '"' + val.replace(/"/g, '""') + '"';
    }
    return val;
  }).join(';') + '\n';
}
);

const filename = `${exportArgs.exportType}_${exportArgs.startDate}_${exportArgs.endDate}.csv`;

return {
  json: {
    hasData: true,
    filename,
    chatId: exportArgs.chatId,
    messageId: exportArgs.messageId
  },
  binary: {
    data: {
      data: Buffer.from(csv, 'utf-8').toString('base64'),
      mimeType: 'text/csv',
      fileName: filename
    }
  }
};

// Parse status command: /status Иванов собеседование
const input = $input.item.json;
const args = input.args;

// Разбираем: имя/часть имени + новый статус
const parts = args.split(/\s+/);
if (parts.length < 2) {
  return { json: { isValid: false, error: 'Формат: /status <ФИО> <статус>', ...input } };
}

const newStatus = parts[parts.length - 1].toLowerCase();
const nameQuery = parts.slice(0, -1).join(' ');

const validStatuses = ['направлен', 'собеседование', 'оформление', 'работает', 'отказ', 'архив'];
if (!validStatuses.includes(newStatus)) {
  return { json: { isValid: false, error: `Неверный статус. Доступные: ${validStatuses.join(', ')}`, ...input } };
}

return { json: { isValid: true, nameQuery, newStatus, ...input } };

// Process found candidates
const candidates = $input.all().map(i => i.json).filter(c => c.id);
const statusArgs = $('Parse Status Args').item.json;

if (!candidates.length) {
  return { json: { found: false, text: `❌ Кандидат "${statusArgs.nameQuery}" не найден.`, chatId: statusArgs.chatId, messageId: statusArgs.messageId } };
}

if (candidates.length === 1) {
  return { json: { found: true, single: true, candidate: candidates[0], newStatus: statusArgs.newStatus, chatId: statusArgs.chatId, messageId: statusArgs.messageId } };
}

// Multiple candidates - ask to choose
let text = `🔍 Найдено ${candidates.length} кандидатов:\n\n`;
const keyboard = { inline_keyboard: [] };

candidates.forEach((c, i) => {
  text += `${i+1}. ${c.full_name} (${c.status})\n`;
  keyboard.inline_keyboard.push([{ text: `${i+1}. ${c.full_name}`, callback_data: `status_set_${c.id}_${statusArgs.newStatus}` }]);
});

text += '\nВыберите кандидата:';

return { json: { found: true, single: false, text, keyboard, chatId: statusArgs.chatId, messageId: statusArgs.messageId } };
